gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLFunction:
    def __init__(self, func: Callable[[float], float]) -> None:
        self.func = func
        self.wrapper = self.create_wrapper()

    def create_wrapper(self) -> ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.py_object):
        wrapper = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.py_object)
        @wrapper
        def wrapped(x: float, params: ctypes.py_object) -> float:
            return self.func(x)
        return wrapper

def integrate_with_singularity(func: Callable[[float], float], a: float, b: float, c: float) -> Tuple[float, float, int]:
    gsl_function = GSLFunction(func)
    params = ctypes.py_object(gsl_function.wrapper)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    flag = ctypes.c_int()
    gsl.qc25c(byref(result), byref(abserr), byref(flag), a, b, c, params)
    return (result.value, abserr.value, flag.value)

if __name__ == "__main__":
    def test_func(x: float) -> float:
        return 1 / x**2

    result = integrate_with_singularity(test_func, 0.5, 1.0, 1.0)
    print(result)

