class GSLFilterGaussianWorkspace:
    def __init__(self, size, alpha):
        self.workspace = gsl.gsl_filter_gaussian_alloc(size, alpha)

    def apply(self, input_vector, output_vector):
        gsl.gsl_filter_gaussian_conv(input_vector.data, input_vector.size, 1, self.workspace, output_vector.data)

    def free(self):
        gsl.gsl_filter_gaussian_free(self.workspace)

