    rng = GSLRng()
    input_vector = GSLVector(N)
    output_vector = GSLVector(N)
    dxi_vector = GSLVector(N)
    dyi_vector = GSLVector(N)
    d2yi_vector = GSLVector(N)

    for i in range(N):
        xi = rng.get_random_double() * 10.0 - 5.0
        ei = rng.get_random_double() * 2.0 - 1.0
        yi = xi**2 + ei
        input_vector.set_value(i, yi)

