class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data = (ctypes.c_double * (self.rows * self.cols))()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = matrix[i][j]

    def to_c_ptr(self):
        return ctypes.cast(ctypes.pointer(self.data), ctypes.POINTER(ctypes.c_double))

def find_minmax_indices(matrix):
    gsl_matrix = GSLMatrix(matrix)
    min_index = ctypes.c_int()
    max_index = ctypes.c_int()
    gsl.gsl_matrix_minmax_index(gsl_matrix.to_c_ptr(), ctypes.byref(min_index), ctypes.byref(max_index))
    return (min_index.value // gsl_matrix.cols, min_index.value % gsl_matrix.cols, max_index.value // gsl_matrix.cols, max_index.value % gsl_matrix.cols)

