cdef typedef struct {
    float real;
    float imag;
} gsl_complex

cdef extern from "gsl_blas.h":
    void cblas_ccopy(ctypes.c_int N, ctypes.POINTER(gsl_complex) X,
                    ctypes.c_int incX, ctypes.POINTER(gsl_complex) Y,
                    ctypes.c_int incY)

def copy_complex_numbers(N, X, incX, Y, incY):
    cdef gsl_complex *cX = <gsl_complex *>X
    cdef gsl_complex *cY = <gsl_complex *>Y
    cblas_ccopy(N, cX, incX, cY, incY)
    return Y

def assert_test():
    N = 5
    X = (gsl_complex *N)()
    Y = (gsl_complex *N)()
    for i in range(N):
        X[i].real = i + 1.0
        X[i].imag = -i - 1.0
        Y[i].real = 0.0
        Y[i].imag = 0.0

    copy_complex_numbers(N, X, 1, Y, 1)

    for i in range(N):
        assert Y[i].real == X[i].real and Y[i].imag == X[i].imag

def __main__():
    assert_test()

