import ctypes
import numpy as np
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_vector(ctypes.Structure):
    _fields_ = ["data", "stride", "size"]

class gsl_matrix(ctypes.Structure):
    _fields_ = ["data", "tda", "size1", "size2"]

def create_gsl_vector(array):
    data = (array.dtype.type * len(array)).from_buffer_copy(array)
    return gsl_vector(data, 1, len(array))

def create_gsl_matrix(matrix):
    data = (matrix.dtype.type * matrix.size).from_buffer_copy(matrix.flatten(order='F'))
    return gsl_matrix(data, matrix.shape[1], matrix.shape[0])

def extract_numpy_array_from_gsl_vector(vector):
    array = np.frombuffer(vector.data, dtype=vector.data._type_)
    return array[:vector.size]

def extract_numpy_array_from_gsl_matrix(matrix):
    shape = (matrix.size1, matrix.size2)
    order = 'F' if matrix.tda == matrix.size1 else 'C'
    array = np.frombuffer(matrix.data, dtype=matrix.data._type_)
    return array.reshape(shape, order=order)

def qrstep(d, f, U, V):
    d_gsl = create_gsl_vector(np.array(d, dtype=np.double))
    f_gsl = create_gsl_vector(np.array(f, dtype=np.double))
    U_gsl = create_gsl_matrix(np.array(U, dtype=np.double))
    V_gsl = create_gsl_matrix(np.array(V, dtype=np.double))
    gsl.gsl_linalg_qrstep(d_gsl, f_gsl, U_gsl, V_gsl)
    return extract_numpy_array_from_gsl_vector(d_gsl), extract_numpy_array_from_gsl_vector(f_gsl), extract_numpy_array_from_gsl_matrix(U_gsl), extract_numpy_array_from_gsl_matrix(V_gsl)
d = [1.0, 2.0, 3.0]
f = [0.5, 0.5]
U = np.array([[1.0, 0.0], [0.0, 1.0]], dtype=np.double)
V = np.array([[1.0, 0.0], [0.0, 1.0]], dtype=np.double)
d_out, f_out, U_out, V_out = qrstep(d, f, U, V)
print(f"d: {d_out}\nf: {f_out}\nU: \n{U_out}\nV: \n{V_out}")

import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_vector(ctypes.Structure):
    _fields_ = ["data", "stride", "size", "block"]

    @staticmethod
def create_gsl_vector(array):
        return gsl_vector((ctypes.c_double * len(array))(*array), 1, len(array), None)

    def extract_numpy_array(self):
        return ctypes.pythonapi.PyArray_SimpleNewFromData(1, (self.size,), ctypes.c_double, self.data)


class gsl_matrix(ctypes.Structure):
    _fields_ = ["data", "tda", "size1", "size2", "stride", "block"]

    @staticmethod
def create_gsl_matrix(matrix):
        return gsl_matrix((ctypes.c_double * len(matrix[0]))(*matrix[0]), 1, len(matrix), len(matrix[0]), None)

    def extract_numpy_array(self):
        return ctypes.pythonapi.PyArray_SimpleNewFromData(2, (self.size1, self.size2), ctypes.c_double, self.data)


def qrstep(d, f, U, V):
    d_c = gsl_vector.create_gsl_vector(d)
    f_c = gsl_vector.create_gsl_vector(f)
    U_c = gsl_matrix.create_gsl_matrix(U)
    V_c = gsl_matrix.create_gsl_matrix(V)

    gsl.qrstep(d_c, f_c, U_c, V_c)

    d_new = d_c.extract_numpy_array()
    f_new = f_c.extract_numpy_array()
    U_new = U_c.extract_numpy_array()
    V_new = V_c.extract_numpy_array()

    return d_new, f_new, U_new, V_new

