gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLVector:
    def __init__(self, size):
        self.size = size
        self.vector = gsl.gsl_vector_alloc(self.size)
        if not self.vector:
            raise Exception("Failed to allocate vector")
        gsl.gsl_vector_set_zero(self.vector)

    def as_list(self):
        result = [gsl.gsl_vector_get(self.vector, i) for i in range(self.size)]
        return result

    def __del__(self):
        if self.vector:
            gsl.gsl_vector_free(self.vector)

def initialize_gsl_vector(size):
    vector = GSLVector(size)
    return vector.as_list()

