def get_gsl_precision_constants():
    precision_types = ["double", "float", "single-float"]
    constants = {}
    for name in ["gsl_prec_eps", "gsl_prec_sqrt_eps", "gsl_prec_root3_eps", "gsl_prec_root4_eps", "gsl_prec_root5_eps", "gsl_prec_root6_eps"]:
        for precision in precision_types:
            func_name = f"{name}_{precision}"
            try:
                func = getattr(gsl, func_name)
                value = func()
                constants[name] = [float(value), float(value.value), float(value.contents.value)]
            except AttributeError:
                pass
    return constants

