import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

GSLMatrix = ctypes.c_void_p

def create_gsl_matrix(rows, cols):
    return gsl.gsl_matrix_alloc(ctypes.c_size_t(rows), ctypes.c_size_t(cols))

def extract_matrix(matrix_ptr):
    rows = gsl.gsl_matrix_rows(matrix_ptr)
    cols = gsl.gsl_matrix_cols(matrix_ptr)
    result = [[0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result[i][j] = gsl.gsl_matrix_get(matrix_ptr, ctypes.c_size_t(i), ctypes.c_size_t(j))
    return result

def apply_givens_qr(M, N, Q, R, i, j, c, s):
    M_ptr = create_gsl_matrix(len(M), len(M[0]))
    R_ptr = create_gsl_matrix(len(R), len(R[0]))
    for m in range(len(M)):
        for n in range(len(M[m])):
            gsl.gsl_matrix_set(M_ptr, ctypes.c_size_t(m), ctypes.c_size_t(n), M[m][n])
    for r in range(len(R)):
        for c in range(len(R[r])):
            gsl.gsl_matrix_set(R_ptr, ctypes.c_size_t(r), ctypes.c_size_t(c), R[c][r])

    gsl.apply_givens_qr(M_ptr, N, Q, R_ptr, i, j, c, s)

    M_new = extract_matrix(M_ptr)
    R_new = extract_matrix(R_ptr)

    return M_new, R_new

import ctypes

gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.data = gsl.gsl_matrix_calloc(self.rows, self.cols)

    def __del__(self):
        gsl.gsl_matrix_free(self.data)

    @staticmethod
def create_gsl_matrix(rows, cols):
    return GSLMatrix(rows, cols)

    @staticmethod
def extract_matrix(gsl_mat):
    data = [[0.0] * gsl_mat.cols for _ in range(gsl_mat.rows)]
    for i in range(gsl_mat.rows):
        for j in range(gsl_mat.cols):
            data[i][j] = gsl.gsl_matrix_get(gsl_mat.data, i, j)
    return data

apply_givens_qr = gsl.apply_givens_qr
apply_givens_qr.argtypes = [ctypes.c_size_t, ctypes.c_size_t, ctypes.POINTER(GSLMatrix), ctypes.POINTER(GSLMatrix), ctypes.c_int, ctypes.c_int, ctypes.c_double, ctypes.c_double]
apply_givens_qr.restype = None

def apply_rotation(Q, R, i, j, c, s):
    M = create_gsl_matrix(len(Q), len(R[0]))
    N = create_gsl_matrix(len(Q[0]), 1)

    for m in range(len(Q)):
        for n in range(len(Q[m])):
            gsl.gsl_matrix_set(M.data, m, n, Q[m][n])
        for n in range(len(R[0])):
            gsl.gsl_matrix_set(N.data, n, 0, R[n][m])

    apply_givens_qr(len(Q), len(R[0]), M.data, N.data, i, j, c, s)

    for m in range(len(Q)):
        Q[m] = [gsl.gsl_matrix_get(M.data, m, n) for n in range(len(Q[m]))]
    for m in range(len(R[0])):
        R[m][m:] = [gsl.gsl_matrix_get(N.data, n, 0) for n in range(m, len(N.data))]

# Example usage
