class GSLMatrix:
    def __init__(self, matrix):
        self.rows = len(matrix)
        self.cols = len(matrix[0])
        self.data = (ctypes.c_complex * self.rows * self.cols)()
        for i in range(self.rows):
            for j in range(self.cols):
                self.data[i * self.cols + j] = ctypes.c_complex(*matrix[i][j])

    def get_c_matrix_ptr(self):
        return ctypes.byref(self.data)

def list_to_gsl_matrix(matrix):
    gsl_matrix = GSLMatrix(matrix)
    return gsl_matrix.get_c_matrix_ptr()

def add_matrices(matrix_a, matrix_b):
    rows = len(matrix_a)
    cols = len(matrix_a[0])
    result_matrix = [[0+0j] * cols for _ in range(rows)]

    matrix_a_ptr = list_to_gsl_matrix(matrix_a)
    matrix_b_ptr = list_to_gsl_matrix(matrix_b)
    result_ptr = list_to_gsl_matrix(result_matrix)

    gsl.gsl_matrix_add(matrix_a_ptr, matrix_b_ptr)

    for i in range(rows):
        for j in range(cols):
            result_matrix[i][j] = (result_ptr.contents[i * cols + j].real, result_ptr.contents[i * cols + j].imag)

    return result_matrix

