class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.nrows = len(matrix)
        self.ncols = len(matrix[0])
        self.data = (ctypes.c_double * (2 * self.nrows * self.ncols))()
        for i in range(self.nrows):
            for j in range(self.ncols):
                real, imag = matrix[i][j].real, matrix[i][j].imag
                idx = 2 * (i * self.ncols + j)
                self.data[idx] = real
                self.data[idx + 1] = imag
        self.gsl_matrix = gsl.gsl_matrix_complex_alloc(self.nrows, self.ncols)
        for i in range(2 * self.nrows * self.ncols):
            ctypes.memmove(gsl.gsl_matrix.data + i * gsl.sizeof(ctypes.c_double), ctypes.byref(self.data[i]), gsl.sizeof(ctypes.c_double))

    def __del__(self):
        gsl.gsl_matrix_complex_free(self.gsl_matrix)

    def to_list(self):
        result = []
        for i in range(self.nrows):
            row = []
            for j in range(self.ncols):
                idx = 2 * (i * self.ncols + j)
                real = self.data[idx].value
                imag = self.data[idx + 1].value
                row.append(complex(real, imag))
            result.append(row)
        return result

