        raise ValueError(\"Matrices must have the same dimensions\")
    result = gsl.gsl_matrix_complex_alloc(matrix_a.rows, matrix_a.cols)
    gsl.gsl_blas_zgemm(ctypes.c_char_p(b'N'), ctypes.c_char_p(b'N'), 1.0,
                        matrix_a.gsl_matrix, matrix_b.gsl_matrix,
