            filtered_signal[i] = signal[i]
    return filtered_signal

def generate_noisy_signal(N):
    t = np.linspace(0, 2 * np.pi, N)
    signal = np.sin(t) + np.random.normal(0, 0.1, N)
    outliers = np.random.choice(np.arange(N), size=int(N / 10), replace=False)
    signal[outliers] += np.random.normal(5, 2, len(outliers))
    return signal

def calculate_statistics(signal):
    median = np.median(signal)
    sigma_bounds = (median - threshold * np.std(signal), median + threshold * np.std(signal))
    outlier_status = [1 if x < sigma_bounds[0] or x > sigma_bounds[1] else 0 for x in signal]
    return median, sigma_bounds, outlier_status

def main(N, K, t):
    gsl = load_gsl_functions()
    workspace = GSLFilterImpulseWorkspace(K)
    try:
        signal = generate_noisy_signal(N)
        filtered_signal = apply_impulse_filter(signal, workspace, t)
        median, sigma_bounds, outlier_status = calculate_statistics(filtered_signal)

        for i in range(len(signal)):
            print(f"Point {i}: Filtered={filtered_signal[i]:.4f}, Median={median:.4f}, Bounds=({sigma_bounds[0]:.4f}, {sigma_bounds[1]:.4f}), Outlier={'Yes' if outlier_status[i] else 'No'}")
    finally:
        workspace.free()

if __name__ == "__main__":
