def cholesky_decomposition(input_matrix):
    rows = len(input_matrix)
    cols = len(input_matrix[0])
    if rows != cols:
        raise ValueError("Input matrix must be square")

    matrix = gsl_matrix_alloc(rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix_set(matrix, i, j, input_matrix[i][j])

    perm = gsl_permutation_alloc(rows)

    result = gsl_linalg_pcholesky_decomp(matrix, rows)
    if result != GSL_SUCCESS:
        raise RuntimeError(f"GSL error: {result}")

    result_matrix = [[0 for _ in range(cols)] for _ in range(rows)]
    for i in range(rows):
        for j in range(cols):
            result_matrix[i][j] = gsl_matrix_get(matrix, i, j)

    permutation = [gsl_permutation_get(perm, i) for i in range(rows)]

    return result_matrix, permutation

def matrix_set(matrix, i, j, value):
    ctypes.c_double.from_address(matrix[i * cols + j] * ctypes.sizeof(ctypes.c_double)).value = value

