    return Matrix_double_p((ctypes.c_double * (rows * cols))())

def matrix_get(matrix, i, j):
    return ctypes.c_double.from_address(matrix[i * cols + j] * ctypes.sizeof(ctypes.c_double)).value

def gsl_permutation_alloc(size):
    return Perm_double_p((ctypes.c_int * size)())

