cdef class gsl_matrix:
    def __init__(self, data, size1, size2):
        self.data = data
        self.size1 = size1
        self.size2 = size2
        self.p = (ctypes.c_double * (size1 * size2))(*data)
        self.m = gsl.gsl_matrix_view_array(self.p, size1, size2)

cdef class gsl_vector:
    def __init__(self, data):
        self.data = data
        self.size = len(data)
        self.p = (ctypes.c_double * self.size)(*data)
        self.v = gsl.gsl_vector_view_array(self.p, self.size)

def matrix_to_gsl(matrix):
    return gsl_matrix(matrix, len(matrix), len(matrix[0]))

def vector_to_gsl(vector):
    return gsl_vector(vector)

def gsl_matrix_to_list(matrix):
    return [list(row) for row in zip(*matrix.data[:matrix.size1 * matrix.size2])]

def gsl_vector_to_list(vector):
    return list(vector.p[:vector.size])

def ql_decomposition_and_unpack(A, tau):
    A = matrix_to_gsl(A)
    tau = vector_to_gsl(tau)
    q = gsl_matrix([[0.0] * len(A) for _ in range(len(A))])
    l = gsl_matrix([[0.0] * len(A[0]) for _ in range(len(A))])
    gsl.gsl_linalg_QL_decomp(A.m, tau.v)
    gsl.gsl_linalg_QL_unpack(A.m, tau.v, q.m, l.m)
    return (gsl_matrix_to_list(q), gsl_matrix_to_list(l))

