class gsl_function(ctypes.Structure):
    _fields_ = ["function", "params"]

def compute_integral(py_func, a, b, epsabs, epsrel, n):
    func_type = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)
    wrapper = func_wrapper(py_func)
    gsl_fun_ptr = func_type(wrapper.func_wrapper)
    params_ptr = ctypes.pointer(ctypes.py_object(py_func))
    gsl_func = gsl_function(gsl_fun_ptr, params_ptr)

    workspace = gsl.gsl_integration_romberg_alloc(n)
    if not workspace:
        raise MemoryError("Failed to allocate Romberg workspace")

    result_ptr = ctypes.POINTER(ctypes.c_double)()
    abserr_ptr = ctypes.POINTER(ctypes.c_double)()
    gsl.gsl_integration_romberg(gsl_func, a, b, epsabs, epsrel, n, workspace, result_ptr, abserr_ptr)

    result = result_ptr.contents.value
    neval = workspace.contents.neval

    gsl.gsl_integration_romberg_free(workspace)

    return result, neval

def func_wrapper(py_func):
    class FuncWrapper:
        def __init__(self, py_func):
            self.py_func = py_func

        def func_wrapper(self, x, params):
            py_func = ctypes.pythonapi.PyObject_GetAttrString(params.contents, "py_func")
            result = py_func(x)
            return ctypes.c_double(result)

    return FuncWrapper(py_func)

