def validate_input(v1, v2):
    if not (isinstance(v1, list) and isinstance(v2, list)):
        raise ValueError("Both inputs must be lists.")
    if not (all(isinstance(i, float) for i in v1) and all(isinstance(i, float) for i in v2)):
        raise ValueError("All elements of the input lists must be floats.")
    if len(v1) != len(v2):
        raise ValueError("Both lists must have the same length.")

def compute_dot_product(vector_x, vector_y):
    gsl = load_gsl_libraries()
    validate_input(vector_x, vector_y)
    n = len(vector_x)
    cblas_ddot = gsl.cblas_ddot
    cblas_ddot.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int]
    cblas_ddot.restype = ctypes.c_double
    x_ptr = (ctypes.c_double * n)(*vector_x)
    y_ptr = (ctypes.c_double * n)(*vector_y)
    return cblas_ddot(n, x_ptr, 1, y_ptr, 1)

