# Define QuantileWorkspace class
class GslRstatQuantileWorkspace:
    def __init__(self, capacity):
        self.workspace = gsl.gsl_rstat_quantile_alloc(capacity)
        if not self.workspace:
            raise MemoryError("Failed to allocate GSL quantile workspace")

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self.workspace, value)

    def get_quantile(self, p):
        if p < 0 or p > 1:
            raise ValueError("Quantile p must be between 0 and 1")
        return ctypes.c_double.in_dll(gsl, 'gsl_rstat_quantile_get').from_address(self.workspace.contents.get_quantile(p).value)

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace)

