ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
def convert_string_to_long(nptr, base, endptr=None):
    if endptr is None:
        endptr_type = ctypes.c_char_p()
        endptr_value = ctypes.create_string_buffer(1)
    else:
        endptr_type = type(endptr)
        endptr_value = ctypes.cast(endptr, endptr_type)
    nptr_cstr = nptr.encode('utf-8')
    result = gsl.convert_string_to_long(nptr_cstr, base, endptr_value)
    if endptr is None:
        return result, endptr_value.value.decode('utf-8')
    else:
        return result

